// a job granted later by a release is placed by recency alone, and its
// prefix, if the slot happens to hold one, is still found in claim.
func (s *llmSched) grant(ids []int32, arrived *llmJob) {
	for {
		w := s.bestWaiter()
		if w == nil {
			return
		}
		var prompt []int32
		if w == arrived {
			prompt = ids
		}
		slot := s.freeSlot(w.class, prompt)
